+
+func trimCredentialedURIEnd(s string, start, end int) int {
+	for end > start {
+		switch s[end-1] {
+		case '.', ',', ';', ':', '!', '?', ')', ']', '}':
+			end--
+		default:
+			return end
+		}
+	}
+	return end
+}
+
+func hasURIUserPassword(candidate string) bool {
+	u, err := url.Parse(candidate)
+	if err != nil || u.Scheme == "" || u.Host == "" || u.User == nil {
+		return false
+	}
+	password, ok := u.User.Password()
+	return ok && password != ""
